#include <iostream>
#include <string>
#include <vector>

/* Remove every reading that is outside [lo, hi], in place, and report
   how many were removed.

   This implementation is BROKEN, and it is wrong in a way that
   depends on the data: some inputs come out right. Find the bug and
   fix it; the specification is in the problem statement, and any
   implementation that meets it is accepted. */
static int prune(std::vector<int>& v, int lo, int hi) {
    int removed = 0;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (v[i] < lo || v[i] > hi) {
            v.erase(v.begin() + i);
            ++removed;
        }
    }
    return removed;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0, lo = 0, hi = 0;
    if (!(std::cin >> n >> lo >> hi)) return 0;
    std::vector<int> v(n);
    for (int& x : v) std::cin >> x;

    const int removed = prune(v, lo, hi);

    std::cout << "removed " << removed << '\n';
    std::cout << "kept " << v.size() << '\n';
    for (std::size_t i = 0; i < v.size(); ++i) {
        std::cout << v[i] << (i + 1 == v.size() ? '\n' : ' ');
    }
    if (v.empty()) std::cout << '\n';
    return 0;
}
